import{_ as r,C as t,o,c as s,j as a,a as l,E as h,a5 as n}from"./chunks/framework.D_J2JZBr.js";const m=JSON.parse('{"title":"EE115B 数字电路","description":"从布尔逻辑、组合电路和时序电路走向 HDL 与有限状态机设计。","frontmatter":{"title":"EE115B 数字电路","description":"从布尔逻辑、组合电路和时序电路走向 HDL 与有限状态机设计。"},"headers":[],"relativePath":"shanghaitech/courses/ee115b.md","filePath":"shanghaitech/courses/ee115b.md","lastUpdated":1795531638000}'),c={name:"shanghaitech/courses/ee115b.md"};function g(d,e,u,p,b,f){const i=t("CourseTable");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"ee115b-数字电路",tabindex:"-1"},[l("EE115B 数字电路 "),a("a",{class:"header-anchor",href:"#ee115b-数字电路","aria-label":'Permalink to "EE115B 数字电路"'},"​")],-1)),h(i,{codes:"EE115B"}),e[1]||(e[1]=n('<p>课程表采用 <strong>2026–2027 学年</strong>开课信息；经验为 <strong>2026 春版本</strong>。往届版本教师可能不同，作业语言和考核以当学期大纲为准。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>本课把<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/si100b">SI100B</a>中的门电路直觉推进为可分析、可描述和可验证的数字系统。官方先修为 EE111；学习上建议先熟悉二进制、基本电路量与逻辑门。</p><p>它是<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">数字集成电路 I</a>、FPGA、嵌入式系统与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee219">智能计算系统</a>的重要基础，也与<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cs110">CS110</a>的数据通路章节相互补充。两门课有重合不等于可以互相替代：本课重点是逻辑和电路，体系结构更关注指令与系统组织。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>2026 春笔记呈现以下学习顺序，具体讲次可能随班级调整：</p><ol><li><strong>表示信息</strong>：数制转换、二进制运算、编码与检错。明确位宽和符号规则，再计算结果。</li><li><strong>表达与化简逻辑</strong>：布尔代数、真值表、卡诺图与 Quine–McCluskey 方法；比较两级与多级实现。</li><li><strong>搭建组合模块</strong>：加法器、算术逻辑单元（ALU）、编码译码器、多路选择器、比较器，以及冒险现象。</li><li><strong>学习硬件描述语言（Hardware Description Language，HDL）</strong>：理解 VHDL / Verilog 的结构、并行语义、仿真与测试平台，而不是逐行“执行程序”。</li><li><strong>引入状态</strong>：锁存器、触发器、移位寄存器、计数器；建立与保持时间、复位和时钟。</li><li><strong>描述系统行为</strong>：有限状态机（Finite State Machine，FSM）、Moore / Mealy 模型、状态编码与寄存器传输级（RTL）实现。</li><li><strong>连接实际硬件</strong>：CMOS、存储器与存储扩展，以及模数 / 数模转换基础。</li></ol><p>学习关键是把“功能正确”和“时序正确”分开检查：真值表正确并不能证明某个寄存器在目标时钟下能稳定工作。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>2026 春项目为 <strong>Subway Turnstile Controller</strong>：用 Moore FSM 分阶段实现闸机控制器，从正常通行扩展到双传感器、反向闯入报警和超时保护。项目使用 Verilog、Icarus Verilog（<code>iverilog</code>）与 GTKWave，要求用状态图和波形解释实现。</p><p>项目内部评分为四个模块各 20 分、报告 20 分，总计 100 分；<strong>这是项目内部配分，不是课程总评占比</strong>。这里介绍任务类型，不提供可直接提交的 RTL。</p><p>可迁移的设计方法是：先将文字要求变成状态与转移条件，再列出同时输入时的优先级，最后为复位、计数边界、异常输入和正常通行分别构造测试。对于安全相关行为，不能只验证“人顺利走过”这一条路径。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li>以本学期课程讲义和任务书为主；现有资料不足以确认所有班级统一使用的教材版本。</li><li><a href="https://hdlbits.01xz.net/" target="_blank" rel="noreferrer">HDLBits</a>：适合练习 Verilog 组合与时序语义，不替代课程项目要求。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/resources">数字自学路线</a>：补充逻辑、HDL 与验证练习。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/tools/open-source/">开源 EDA</a>：了解仿真与波形工具在流程中的位置。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 春版本。</strong> 可确认有作业和状态机项目，但完整总评比例未由现有笔记可靠给出；本页不补造考试、实验或出勤权重。</p><ul><li><strong>难点</strong>：组合逻辑与时序逻辑的语义、非阻塞赋值、复位行为，以及计数器的差一拍问题。</li><li><strong>准备</strong>：每学一种模块，都先写输入输出定义和预期行为，再写代码。不要通过反复改 <code>always</code> 块“试到波形看起来对”。</li><li><strong>工具链</strong>：先完成编译、生成 VCD、打开波形的最小闭环；错误发生时同时查看输入、状态、计数器和输出，而非只看最后一个端口。</li><li><strong>交付</strong>：报告逐项关联状态图、实现意图与波形证据。按任务书组织文件，不能假设评测会自动寻找任意目录下的模块。</li><li><strong>诚信</strong>：2026 春项目笔记记录了禁止使用 AI 代写 RTL 的要求；新学期须重新确认政策。允许使用工具辅助理解，不代表允许代写或代交。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/digital-vlsi">数字 VLSI</a>：逻辑如何映射到真实电路。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/architecture">计算机体系结构</a>：数据通路、控制器与处理器。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/hardware-security">硬件安全</a>：异常状态与验证边界的重要性。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过这门课，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>补充不同班级与学期的工具链、实验安排及学习建议。不公开可直接提交的项目代码。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：教师、学分与先修。</li><li>维护者 2026 春课程笔记《数字电路 EE115B》《EE115B Project — Subway Turnstile Controller》：内容与项目经验；规则仍以当学期任务书为准。</li></ul>',22))])}const _=r(c,[["render",g]]);export{m as __pageData,_ as default};
